fn find_max(nums: Vec<i32>) -> i32 {
    // Since nums is non-empty, we can safely take the first element as the initial maximum.
    let mut max_val = nums[0];

    // Iterate over the rest of the elements, updating max_val whenever we find a larger one.
    for &x in &nums[1..] {
        if x > max_val {
            max_val = x;
        }
    }

    max_val
}

fn main() {
    let v1 = vec![3, 1, 4, 1, 5, 9, 2];
    let v2 = vec![-10, -3, -25, -1];
    let v3 = vec![42];

    assert_eq!(find_max(v1), 9);
    assert_eq!(find_max(v2), -1);
    assert_eq!(find_max(v3), 42);

    println!("All tests passed!");
}